def lesson_text(i: int) -> str:
    title, essence, here = LESSONS[i % len(LESSONS)]
    return f"📘 Урок {i % len(LESSONS) + 1} из {len(LESSONS)} · {title}\n{essence}\n🧩 У нас: {here}"
